package com.eventpulse.service;
import com.eventpulse.dto.*; import com.eventpulse.exception.*; import com.eventpulse.model.Event; import com.eventpulse.repository.EventRepository; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class EventServiceTest { EventRepository repo; EventService service; @BeforeEach void setup(){repo=mock(EventRepository.class);service=new EventService(repo,Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC));} CreateEventRequest valid(){return new CreateEventRequest("Town Hall","desc","Community","Hall","2027-01-01T10:00:00Z","2027-01-01T11:00:00Z");}
 @Test void createsFutureEventAsUpcoming(){when(repo.save(any())).thenAnswer(i->i.getArgument(0));Event e=service.create(valid(),"admin");assertNotNull(UUID.fromString(e.getEventId()));assertEquals("UPCOMING",e.getStatus());assertEquals("admin",e.getCreatedBy());}
 @Test void createsPastEventAsCompletedAtEndBoundary(){when(repo.save(any())).thenAnswer(i->i.getArgument(0));var past=new CreateEventRequest("Town Hall","desc","Community","Hall","2025-12-31T22:00:00Z","2026-01-01T00:00:00Z");assertEquals("COMPLETED",service.create(past,"admin").getStatus());}
 @Test void derivesCompletedWhenEndEqualsNowAndOngoingAfterStartBoundary(){Event atBoundary=new Event();atBoundary.setStatus("UPCOMING");atBoundary.setStartDateTime("2025-12-31T23:00:00Z");atBoundary.setEndDateTime("2026-01-01T00:00:00Z");assertEquals("COMPLETED",EventService.statusAt(atBoundary,Instant.parse("2026-01-01T00:00:00Z")));Event inProgress=new Event();inProgress.setStatus("UPCOMING");inProgress.setStartDateTime("2026-01-01T00:00:00Z");inProgress.setEndDateTime("2026-01-01T01:00:00Z");assertEquals("ONGOING",EventService.statusAt(inProgress,Instant.parse("2026-01-01T00:00:00Z")));}
 @Test void derivesStatusOnReadWithoutPersistingAndPreservesCancellation(){Event event=new Event();event.setEventId("id");event.setStatus("UPCOMING");event.setStartDateTime("2025-12-31T23:00:00Z");event.setEndDateTime("2026-01-01T00:00:00Z");when(repo.findById("id")).thenReturn(Optional.of(event));assertEquals("COMPLETED",service.get("id").getStatus());verify(repo,never()).save(any());event.setStatus("CANCELLED");assertEquals("CANCELLED",service.get("id").getStatus());}
 @Test void rejectsEndBeforeStart(){var r=new CreateEventRequest("x","d","c","v","2027-01-01T11:00:00Z","2027-01-01T10:00:00Z");assertThrows(ValidationException.class,()->service.create(r,"u"));}
 @Test void missingEventIsMeaningful(){when(repo.findById("x")).thenReturn(Optional.empty());assertThrows(EventNotFoundException.class,()->service.get("x"));}
 @Test void updateChangesFields(){Event e=new Event();e.setEventId("id");e.setStatus("UPCOMING");when(repo.findById("id")).thenReturn(Optional.of(e));when(repo.save(any())).thenAnswer(i->i.getArgument(0));var updated=service.update("id",new UpdateEventRequest("new","desc","cat","venue","2027-01-01T10:00:00Z","2027-01-01T11:00:00Z"));assertEquals("new",updated.getTitle());}
 @Test void cancellationIsSoft(){Event e=new Event();e.setEventId("id");e.setStatus("UPCOMING");when(repo.findById("id")).thenReturn(Optional.of(e));when(repo.save(any())).thenAnswer(i->i.getArgument(0));assertEquals("CANCELLED",service.cancel("id").getStatus());}
}
